@pytest.mark.parametrize("result_callback", [True, False])
def test_with_result_memorized(pm: PluginManager, result_callback: bool) -> None:
    """Verify that ``HookCaller._maybe_apply_history()`
    correctly applies the ``result_callback`` function, when provided,
    to the result from calling each newly registered hook.
    """
    out = []
    if not result_callback:
        callback = None
    else:

        def callback(res) -> None:
            out.append(res)

    class Hooks:
        @hookspec(historic=True)
        def he_method1(self, arg):
            pass

    pm.add_hookspecs(Hooks)

    class Plugin1:
        @hookimpl
        def he_method1(self, arg):
            return arg * 10

    pm.register(Plugin1())

    he_method1 = pm.hook.he_method1
    he_method1.call_historic(result_callback=callback, kwargs={"arg": 1})

    class Plugin2:
        @hookimpl
        def he_method1(self, arg):
            return arg * 10

    pm.register(Plugin2())
    if result_callback:
        assert out == [10, 10]
    else:
        assert out == []

def test_historic_replay(self, pm: PluginManager) -> None:
    """Test historic calls respect defaults."""

    class Api:
        @hookspec(historic=True)
        def hello(self, arg, new_arg="spec"):
            pass

    pm.add_hookspecs(Api)

    pm.hook.hello.call_historic(kwargs={"arg": 1})
    pm.hook.hello.call_historic(kwargs={"arg": 2, "new_arg": "call"})

    seen = []

    class Plugin:
        @hookimpl
        def hello(self, arg, new_arg):
            seen.append((arg, new_arg))

    pm.register(Plugin())

    assert seen == [(1, "spec"), (2, "call")]
